COPY analysis_state FROM '__FIXTURE_DIRECTORY__/analysis_state.csv' (FORMAT 'csv', force_not_null ('project_id', 'state_key', 'value_json', 'etag', 'updated_at_unix_nano'), quote '"', delimiter ',', HEADER 1);
COPY annotations FROM '__FIXTURE_DIRECTORY__/annotations.csv' (FORMAT 'csv', force_not_null ('project_id', 'annotation_id', 'target_kind', 'text', 'created_at_unix_nano', 'updated_at_unix_nano', 'etag'), quote '"', delimiter ',', HEADER 1);
COPY idempotency_keys FROM '__FIXTURE_DIRECTORY__/idempotency_keys.csv' (FORMAT 'csv', force_not_null ('project_id', 'operation', 'idempotency_key', 'request_hash', 'resource_id', 'response_json', 'created_at_unix_nano'), quote '"', delimiter ',', HEADER 1);
COPY logs FROM '__FIXTURE_DIRECTORY__/logs.csv' (FORMAT 'csv', force_not_null ('project_id', 'log_id', 'time_unix_nano', 'severity_number', 'ingest_sequence'), quote '"', delimiter ',', HEADER 1);
COPY metric_exemplars FROM '__FIXTURE_DIRECTORY__/metric_exemplars.csv' (FORMAT 'csv', force_not_null ('project_id', 'series_id', 'time_unix_nano', 'trace_id'), quote '"', delimiter ',', HEADER 1);
COPY metric_points FROM '__FIXTURE_DIRECTORY__/metric_points.csv' (FORMAT 'csv', force_not_null ('project_id', 'series_id', 'time_unix_nano'), quote '"', delimiter ',', HEADER 1);
COPY metric_series FROM '__FIXTURE_DIRECTORY__/metric_series.csv' (FORMAT 'csv', force_not_null ('project_id', 'series_id', 'metric_name', 'metric_kind', 'temporality', 'is_monotonic', 'first_seen_unix_nano', 'last_seen_unix_nano'), quote '"', delimiter ',', HEADER 1);
COPY qyl_schema_meta FROM '__FIXTURE_DIRECTORY__/qyl_schema_meta.csv' (FORMAT 'csv', force_not_null ('singleton', 'authoritative_schema_hash', 'derived_schema_hash', 'updated_at'), quote '"', delimiter ',', HEADER 1);
COPY saved_queries FROM '__FIXTURE_DIRECTORY__/saved_queries.csv' (FORMAT 'csv', force_not_null ('project_id', 'saved_query_id', 'name', 'signal', 'filter_json', 'created_at_unix_nano', 'updated_at_unix_nano', 'etag'), quote '"', delimiter ',', HEADER 1);
COPY spans FROM '__FIXTURE_DIRECTORY__/spans.csv' (FORMAT 'csv', force_not_null ('project_id', 'span_id', 'trace_id', 'name', 'kind', 'start_time_unix_nano', 'end_time_unix_nano', 'duration_ns', 'status_code'), quote '"', delimiter ',', HEADER 1);
